<?phpdeclare(strict_types=1);$root = realpath($argv[1] ?? getcwd());if (false === $root) { fwrite(STDERR, "Invalid root path.\n"); exit(2); }$path = $root."/config/packages/navigation.yaml";if (!is_file($path)) { fwrite(STDERR, "config/packages/navigation.yaml is missing.\n"); exit(2); }$content = (string) file_get_contents($path);$bad = ["/ea/administering" => "Use /ea/administration.", "/ea/config" => "Use /ea/administration/config.", "/ea/command" => "Use /ea/administration/command/...", "/ea/runtime" => "Use /ea/administration/runtime/...", "/ea/operation" => "Use /ea/administration/operation."];$findings = [];foreach ($bad as $needle => $message) { $offset = 0; while (false !== ($position = strpos($content, $needle, $offset))) { $line = substr_count(substr($content, 0, $position), "\n") + 1; $findings[] = sprintf("config/packages/navigation.yaml:%d contains %s. %s", $line, $needle, $message); $offset = $position + strlen($needle); } }foreach (["/ea/administration", "/ea/administration/config", "/ea/administration/command/index", "/ea/administration/runtime/scope/application/index", "/ea/administration/operation"] as $needle) { if (!str_contains($content, $needle)) { $findings[] = sprintf("config/packages/navigation.yaml is missing required Administering navigation path %s.", $needle); } }if ([] !== $findings) { fwrite(STDERR, "App navigation EasyAdmin route guard failed:\n"); foreach ($findings as $finding) { fwrite(STDERR, " - ".$finding."\n"); } exit(1); }fwrite(STDOUT, "App navigation EasyAdmin route guard passed.\n");exit(0);